from pathlib import Path
import json,hashlib,html

root=Path(__file__).resolve().parents[1];out=root/'output/semicircle-verification'
read=lambda name:json.loads((out/name).read_text(encoding='utf-8-sig'))
unit=read('unit-results.json');assert unit['success'] and unit['numPassedTests']==352
files=['api-results.json','cutting-results.json','export-note-results.json','ui-results.json','built-results.json']
counts={}
for name in files:
    r=read(name);assert not r.get('errors') and not r.get('cloud');assert all(x['status']=='PASS' for x in r['results']);counts[name]=len(r['results'])
total=unit['numPassedTests']+sum(counts.values());assert total==373
for name in ['demo-build.log','production-build.log']:assert 'built in' in (out/name).read_text('utf8')
hashes=read('unchanged-config.json')
comparison={name:{'baselineSha256':digest,'finalSha256':hashlib.sha256((root/name).read_bytes()).hexdigest()} for name,digest in hashes.items()}
changed={name:data for name,data in comparison.items() if data['baselineSha256']!=data['finalSha256']}
assert set(changed).issubset({'storage.rules'}), 'Unexpected concurrent configuration change; inspect before reporting'
(out/'config-comparison.json').write_text(json.dumps(comparison,indent=2),'utf8')
config_note=('ไฟล์ Auth, clientCommands, firestore.rules และ firebase.json เทียบ hash กับv0.29แล้วคงเดิม แต่ storage.rules เปลี่ยนจากฐานเดิมระหว่างทำงานโดยไม่ระบุผู้แก้ จึงรักษาไฟล์ปัจจุบันไว้และไม่อ้างว่า Rulesทั้งชุดคงเดิม ผลทดสอบนี้มาจาก emulatorที่กำลังทำงาน ไม่ยืนยัน RulesปัจจุบันบนCloud' if changed else 'ไฟล์ Auth, clientCommands, Firestore/Storage Rules และ firebase.json เทียบ hash กับv0.29แล้วคงเดิม ผลทดสอบในเครื่องไม่ยืนยัน RulesบนCloud')
checkpoint=read('checkpoint-verification.json');assert checkpoint['status']=='PASS'
summary={'version':'0.30.0','status':'PASS','softwareScenarios':total,'unitTests':352,'directExportScenarios':counts['api-results.json'],'cutInterop':1,'exportNotes':1,'devUiScenarios':5,'builtUiScenarios':5,'pdfPages':13,'workbookViews':3,'fullSystemAcceptance':False,'engineeringAccepted':False,'rulesDeployment':'User managed; explicitly declined','rulesFilesEditedByThisIncrement':False,'cloudChangesByThisIncrement':False,'unchangedAuthRulesConfig':{name:data['finalSha256'] for name,data in comparison.items() if name not in changed},'finalAuthRulesConfig':{name:data['finalSha256'] for name,data in comparison.items()},'concurrentConfigChanges':changed,'checkpoint':checkpoint}
(out/'verification-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),'utf8')
images=[('built-envelope.png','รูป 13 สองเส้นและมิติ A/B/(C)'),('built-3d.png','ตำแหน่งจริงในสมาชิก — รุ่น build'),('built-mobile.png','หน้าจอมือถือและตารางพิกัด'),('excel-bbs.png','Excel จริง: BBS สำหรับพิมพ์'),('excel-rebar.png','Excel จริง: สรุปเหล็กตามขนาด'),('excel-tolerances.png','Excel จริง: Table4 พร้อมหมายเหตุที่ตัดบรรทัดแล้ว'),('pdf-A3-contact.png','PDF A3 จริง — 4 หน้า'),('pdf-A1-contact.png','PDF A1 จริง — 4 หน้า'),('pdf-A4-contact.png','PDF ตาราง A4 จริง — 5 หน้า')]
for name,_ in images:assert (out/name).is_file()
gallery=''.join(f'<figure><a href="{name}"><img src="{name}" alt="{title}" loading="lazy"></a><figcaption>{title}</figcaption></figure>' for name,title in images)
links=''.join(f'<a class="download" href="{name}">{label}</a>' for name,label in [('BS13-draft.xlsx','Excel ตัวอย่าง Draft'),('BS13-A3-draft.pdf','แบบ A3'),('BS13-A1-draft.pdf','แบบ A1'),('BS13-A4-draft.pdf','ตาราง A4'),('BS13-v3-frozen.xlsx','Excel รุ่น 3 ที่ตรึงไว้'),('BS13-backup.zip','Backup ทดสอบ')])
checks=''.join(f'<li>{html.escape(r["name"])}</li>' for name in files for r in read(name)['results'])
doc=f'''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BOQ & BBS v0.30 — ผลการพัฒนา</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#f3f7f5;color:#203940;font:16px/1.7 system-ui,"Sarabun",sans-serif}}main{{max-width:1180px;margin:auto;padding:32px}}header,section{{background:white;border:1px solid #dce6e1;border-radius:14px;padding:28px;margin-bottom:22px}}h1{{font-size:30px;line-height:1.35}}h2{{font-size:23px}}h3{{font-size:18px}}a{{color:#176b55}}.eyebrow{{color:#537267;font-weight:650}}.status{{background:#fff2d6;color:#714d17;padding:16px;border-radius:8px}}.stats{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}}.stat{{background:#edf5f0;padding:16px;border-radius:8px}}.stat strong{{display:block;font-size:27px}}.downloads{{display:flex;flex-wrap:wrap;gap:10px}}.download{{border:1px solid #b9cfc4;padding:8px 13px;border-radius:6px;text-decoration:none}}.gallery{{display:grid;grid-template-columns:1fr 1fr;gap:18px}}figure{{margin:0;border:1px solid #dce6e1;border-radius:9px;padding:10px;min-width:0}}img{{width:100%;height:280px;object-fit:contain;background:#fafcfb}}figcaption{{font-size:14px;padding-top:8px}}table{{border-collapse:collapse;width:100%}}th,td{{padding:12px;text-align:left;border-bottom:1px solid #dce6e1}}th{{background:#edf5f0}}.scroll{{overflow:auto}}code{{overflow-wrap:anywhere}}li{{margin-bottom:9px}}details{{margin-top:18px}}small{{color:#5d756b}}@media(max-width:640px){{main{{padding:12px}}header,section{{padding:18px}}h1{{font-size:24px}}.stats{{grid-template-columns:1fr 1fr}}.gallery{{grid-template-columns:1fr}}img{{height:auto;max-height:600px}}}}
</style><main><header><div class="eyebrow">FORM BOQ & BBS · v0.30 · 12 ตุลาคม 2026</div><h1>เพิ่มรูปดัด 13 และคงผลคำนวณของ Revision เดิม</h1><p>รูปครึ่งวงกลม 180° จาก BS8666 ที่ผู้ใช้ให้ไว้ ใช้มิติ A/B/(C) ผิวนอกกำหนดส่วนโค้งจริง พร้อมสูตรตาราง ความยาวแนวศูนย์กลาง และไฟล์ส่งออกจากระบบ</p><div class="status"><b>ผ่านเฉพาะขอบเขตซอฟต์แวร์ที่ทดสอบ — ยังไม่ผ่านการตรวจรับระบบเต็มหรือวิศวกรรม</b><br>ตัวอย่างทั้งหมดเป็นข้อมูลทดสอบในเครื่อง ไม่มีแบบเจ้าของงานจริงที่ตรวจรับในรอบนี้ Issued และการตัดใช้สต็อก Production ยังปิดอยู่</div><div class="stats"><div class="stat"><strong>{total}</strong>กรณีซอฟต์แวร์ผ่าน</div><div class="stat"><strong>13</strong>หน้า PDF จริงที่เรนเดอร์</div><div class="stat"><strong>3</strong>ช่วงตาราง Excel ที่ตรวจภาพ</div><div class="stat"><strong>0</strong>deploy Rules ในรอบนี้</div></div><div class="downloads">{links}</div></header>
<section><h2>สิ่งที่เพิ่มในแอป</h2><ul><li>ชุดกฎขั้นต่ำรุ่น4 เพิ่มรูป13 โครงการใหม่ใช้รุ่น4 โครงการเดิมต้องเลือกและบันทึกอย่างชัดเจน จึงล้างการยืนยันสมาชิกและคืน Draft; รุ่น1/2/3 และ Frozen เดิมคงฐานคำนวณเดิม</li><li>สร้างจาก A/B/C ทีละ5mm โดย B กำหนด Rศูนย์กลางและ rด้านใน ตรวจทั้ง Table3 มิติปลาย5d และมิติของรูป13 ไม่มีการสร้างเป็น U มุมคมหรือใช้รหัสรูปแทนการตรวจ geometry</li><li>ส่วนโค้ง90° สองส่วนใช้ศูนย์เดียวกันเป็นครึ่งวงกลมหนึ่งส่วน L02 ตรง=0 คือจุดต่อส่วนโค้ง พร้อมคำอธิบายบนหน้าจอและแบบ ไม่ใช้ข้อยกเว้นนี้กับ U ทั่วไป</li><li>รูป2D/3D แบบผิวเหล็กสองเส้น Excel/A3/A1/A4 และแผนตัดใช้ฐานยาวตัดเดียวกัน มิติอิสระ(C) แสดงชัด ปรับเส้นชี้รัศมีและตัดบรรทัดหมายเหตุ Excel ให้ไม่ทับมิติหรือขาดข้อความ</li></ul></section>
<section><h2>กรณีตัวเลขที่ตรวจอิสระ</h2><div class="scroll"><table><thead><tr><th>ข้อมูล mm</th><th>สูตร Table1</th><th>แนวศูนย์กลางจริง</th><th>ยาวตัดใช้กับ BOQ</th></tr></thead><tbody><tr><td>A1005/B100/C225/d16</td><td>1261.88</td><td>1261.9469</td><td>1275</td></tr><tr><td>A1000/B285/C300/d8</td><td>1449.89</td><td>1450.1106</td><td>1450</td></tr></tbody></table></div><p>ใช้สัมประสิทธิ์0.57/1.57 ตามเอกสาร ไม่แทนด้วยπเงียบ ๆ กรณีที่สองจะเป็น1475mm ถ้าปัดความยาวจริงแยกต่างหาก จึงแสดงสองฐานให้ผู้ตรวจเห็นและต้องมีกรณีวิศวกรรมที่รับรองก่อนผลิต</p><p>แผนตัดจาก Worker จริงตรวจอีกกรณี: Working5สมาชิก ×2เส้นต่อMark รวม30เส้น ยาวตัดรวม40000mm แบ่งØ8สิบเส้นที่1450mm และØ16ยี่สิบเส้นที่1275mm ไม่มีการคูณซ้ำ ส่วน Frozen ที่ใช้ส่งออกยังคง3สมาชิกและ18เส้น</p></section>
<section><h2>ขอบเขตการตรวจ</h2><p>352 unit tests +9 direct/export +1 แผนตัด +1 ตรวจหมายเหตุ Excel +5 หน้าจอ dev +5 หน้าจอ build =373 กรณี PDF/ภาพตารางตรวจเพิ่มแยกจากจำนวนนี้ Build ทั้ง demo และค่าตั้ง Production ผ่าน แต่ยังไม่ได้ deploy</p><ul><li>PDF ที่ตรวจเป็นไฟล์ generateJob/upload/download จริง: A3สี่หน้า A1สี่หน้า และ A4ห้าหน้า ไม่ใช่ diagnostic ที่สร้างแทนระบบ</li><li>Excel นำไฟล์ที่ดาวน์โหลดจริงมาเปิด ตรวจชนิดข้อมูล สูตร รูปเส้นโค้ง และคำนวณใหม่ เปลี่ยน inputชั่วคราวในสำเนาตรวจเพื่อทดสอบการเชื่อมสูตร แล้วคืนค่าก่อนเรนเดอร์ ไม่อ้างว่าได้พิมพ์จาก Microsoft Excel จริง</li><li>กู้คืน Backup จริงได้สมาชิกและชุดกฎรุ่น4 แต่ล้างการยืนยัน ส่วน Revision รุ่น3/4เก็บเป็น importedHistory อ้างอิง พร้อมไฟล์และ checksum ไม่สร้างเป็น Issued และไม่คืน ACL จากต้นทาง</li><li>ผู้ใช้ viewerอ่านโครงการที่ได้รับมอบหมายได้แต่แก้ geometry/Specไม่ได้ อีกโครงการที่ไม่มีสิทธิ์ถูกปฏิเสธ ใช้ Firebase SDKกับ emulator; ไม่ทดสอบผู้ใช้ Productionหรือ RulesบนCloud</li></ul><details><summary>กรณีเชื่อมต่อและหน้าจอที่ผ่าน</summary><ul>{checks}</ul></details></section>
<section><h2>หลักฐานภาพ</h2><p>คลิกภาพเพื่อดูขนาดเต็ม ภาพมือถือยืนยันการจัดพื้นที่และการเลื่อนตาราง; รายละเอียดมิติให้ตรวจร่วมกับตารางและไฟล์ส่งออก</p><div class="gallery">{gallery}</div></section>
<section><h2>มาตรฐานและข้อมูลที่รักษาไว้</h2><p>ที่มา <a href="../../Referrence/BS%208666.pdf">BS8666 ที่ผู้ใช้ให้ไว้</a>: BS8666:2000 +Amd1/2; Table1 หน้า6 / Note2หน้า8 / Table3หน้า11 อ่านทั้งข้อความและภาพ ชุดนี้เป็นมาตรฐานขั้นต่ำตามไฟล์ที่ให้ ไม่อ้างเป็นการตรวจครบทุกข้อหรือปีฉบับใหม่</p><p><code>SHA256 9c6fa5d0bafd0a8761f14d1611c582d5db7d89710eaaf0910b5dc7c493e0cb43</code></p><p>Note2: ระบบพักการตรวจผ่านเมื่อ Rศูนย์กลาง&gt;200mm เป็นเงื่อนไขของแอปเพื่อรอผู้ผลิต ไม่ตีความเป็นนิยามรัศมีที่แม่นยำของมาตรฐานและไม่จำลองการแบ่งโค้งเป็นช่วงตรงเอง</p><p>{config_note}</p><p>ผู้ใช้กำหนดและ deploy Rulesเองตามคำตอบล่าสุด งานv0.30นี้ไม่เขียนไฟล์ Rules/.env ไม่เพิ่ม Cloud Functions ไม่ deployหรือแก้ข้อมูลCloud ดู <a href="config-comparison.json">หลักฐานเทียบไฟล์ตั้งค่า</a></p><p>สำรอง Auth/Firestore/Storage emulatorไว้ที่ <code>{html.escape(checkpoint['checkpoint'])}</code> ตรวจ Storage{checkpoint['storageBlobs']}รายการด้วยขนาด/MD5 และรักษา SHA256ของ{checkpoint['previousV29BlobsSha256Preserved']}รายการเดิมv0.29ทั้งหมด ไม่แทน .emulator-data ไม่ reimport และไม่อ้างการเทียบฐานข้อมูลทั้งชุดหรือการกู้คืน Production</p></section>
<section><h2>งานเดิมที่ยังต้องทำก่อนใช้จริง</h2><ul><li>BS shapes33/51/67/77, กฎ ACI318 hooks/lap/development และค่าคลาดเคลื่อนสะสม/มิติอิสระ พร้อมกรณีที่ผู้รับผิดชอบรับรอง</li><li>ชุดข้อมูลโครงการ GULF และแบบเจ้าของงานจริง รวมรูปทรงและรายละเอียดที่ยังไม่รองรับ การตรวจรับ A3/A1/title block และการพิมพ์ Excelจริง</li><li>Productionกับ Rulesที่ผู้ใช้จัดการ สิทธิ์บัญชีจริง โหลดระดับโครงการจริง การปฏิบัติการและการกู้คืน ต้องตรวจแยก ก่อนเปิด Issuedหรือใช้งานผลิต</li></ul><small>รายงานนี้ระบุเฉพาะการพัฒนาและหลักฐานที่ตรวจได้ในรอบv0.30 ไม่ใช่การรับรองงานวิศวกรรมหรือการตรวจรับทั้งแอป</small></section></main></html>'''
(out/'DEVELOPMENT_REPORT.html').write_text(doc,'utf8');print(f'PASS: report generated from {total} scoped scenarios')
